[tikz]
\begin{tikzpicture}[every node/.style={font=\large},draw=black]
\definecolor{waterBlue}{HTML}{268CFF}
\draw (0,3.4)--(0,0)--(2,0)--(2,3.4); \draw (4,3.4)--(4,0)--(6,0)--(6,3.4);
\draw[waterBlue] (0,0.72)--(2,0.72) node[midway,above] {$240\text{ mL}$};
\draw[waterBlue] (4,0.95)--(6,0.95) node[midway,above] {$315\text{ mL}$};
\node[below] at (1,0) {Before}; \node[below] at (5,0) {After};
\draw[black] (5,0.5) circle (0.2);
\end{tikzpicture}
[/tikz]

